import { PlaneGeometry, BoxGeometry, CircleGeometry, Mesh, Group, Color, SRGBColorSpace } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const visualSpec = config.intent?.visualSpec ?? {};
  const palette = visualSpec.colors ?? {};

  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const root = new Group();
  root.name = 'collection-card-1';
  root.userData.handlers = {};

  const ownedGeometries = [];
  const ownedMaterials = [];
  const primitiveResults = [];
  let disposed = false;

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makeMesh = (geometry, material, name) => {
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.name = name;
    root.add(mesh);
    return mesh;
  };

  const backdropMaterial = makeBasicMaterial();
  const bottomColor = uniform(new Color(surface));
  const middleColor = uniform(new Color(ink));
  const topColor = uniform(new Color('#24242d'));
  const gradientY = uv().y;
  const lowerBlend = smoothstep(0.0, 0.58, gradientY);
  const upperBlend = smoothstep(0.42, 1.0, gradientY);
  backdropMaterial.colorNode = mix(
    mix(bottomColor, middleColor, lowerBlend),
    topColor,
    upperBlend
  );

  const backdrop = makeMesh(
    new PlaneGeometry(7, 6),
    backdropMaterial,
    'engineered-gradient-backdrop'
  );
  backdrop.position.set(0, 0, -2.5);

  const shadowMaterial = makeBasicMaterial({
    color: new Color('#050509'),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = makeMesh(
    new CircleGeometry(1.75, 64),
    shadowMaterial,
    'contact-shadow'
  );
  shadow.scale.set(1.55, 0.27, 1);
  shadow.position.set(0, -1.08, -0.12);
  shadow.rotation.x = 0;

  const cardBackMaterial = makeBasicMaterial({
    color: new Color(ink)
  });
  const cardBack = makeMesh(
    new PlaneGeometry(3.08, 1.965),
    cardBackMaterial,
    'machined-card-back'
  );
  cardBack.position.set(0, 0, -0.08);

  const imageMaterial = makeBasicMaterial({
    color: new Color(paper),
    transparent: false
  });
  const image = makeMesh(
    new PlaneGeometry(3.0, 1.875),
    imageMaterial,
    'collection-card-image'
  );
  image.position.set(0, 0, 0);

  const accentMaterial = makeBasicMaterial({
    color: new Color(accent)
  });

  const accentTop = makeMesh(
    new BoxGeometry(2.98, 0.035, 0.025),
    accentMaterial,
    'signal-red-top-edge'
  );
  accentTop.position.set(0, 0.955, 0.035);

  const accentSide = makeMesh(
    new BoxGeometry(0.035, 0.92, 0.025),
    accentMaterial,
    'signal-red-side-edge'
  );
  accentSide.position.set(1.49, 0.0, 0.035);

  const grainMaterial = makeBasicMaterial({
    color: new Color(paper),
    transparent: true,
    opacity: 0.035,
    depthWrite: false
  });
  const grain = makeMesh(
    new PlaneGeometry(2.94, 1.82),
    grainMaterial,
    'subtle-surface-grain'
  );
  grain.position.set(0, 0, 0.045);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;
      texture.colorSpace = SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entrance.kill();

    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      else if (result.timeline && typeof result.timeline.kill === 'function') {
        result.timeline.kill();
      }
    }

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();

    root.userData.handlers = {};
  };

  return root;
}
